import React from 'react';

const Deck = ({ cardsRemaining }) => {
  return (
    <div className="flex flex-col items-center">
      <h3 className="text-white text-lg font-semibold mb-3">🎰 Draw Pile</h3>
      
      <div className="relative">
        {/* Stacked card effect */}
        {cardsRemaining > 0 && (
          <>
            {cardsRemaining > 4 && (
              <div className="absolute top-2 left-1 w-16 h-24 md:w-20 md:h-28 bg-gradient-to-br from-blue-700 to-blue-900 rounded-lg border-2 border-blue-500"></div>
            )}
            {cardsRemaining > 2 && (
              <div className="absolute top-1 left-0.5 w-16 h-24 md:w-20 md:h-28 bg-gradient-to-br from-blue-600 to-blue-800 rounded-lg border-2 border-blue-400"></div>
            )}
            <div className="relative w-16 h-24 md:w-20 md:h-28 bg-gradient-to-br from-blue-500 to-blue-700 rounded-lg shadow-xl border-2 border-blue-300 flex items-center justify-center">
              <div className="text-3xl md:text-4xl">🂠</div>
            </div>
          </>
        )}
        
        {cardsRemaining === 0 && (
          <div className="w-16 h-24 md:w-20 md:h-28 border-2 border-dashed border-gray-500 rounded-lg flex items-center justify-center bg-gray-800 bg-opacity-50">
            <span className="text-gray-400 text-xs text-center">Empty</span>
          </div>
        )}
      </div>
      
      <div className="mt-3 bg-gray-800 px-4 py-2 rounded-full">
        <span className="text-white font-bold">{cardsRemaining}</span>
        <span className="text-gray-300 text-sm ml-1">cards left</span>
      </div>
    </div>
  );
};

export default Deck;
